import { useState, useRef } from 'react'

export default function TrainModelPage() {
  const [file, setFile]           = useState(null)
  const [dragOver, setDragOver]   = useState(false)
  const [training, setTraining]   = useState(false)
  const [metrics, setMetrics]     = useState(null)
  const [error, setError]         = useState(null)
  const fileRef = useRef()

  // ── File helpers ────────────────────────────────────────────────────────
  function handleDrop(e) {
    e.preventDefault()
    setDragOver(false)
    const dropped = e.dataTransfer.files[0]
    if (dropped && dropped.name.toLowerCase().endsWith('.csv')) {
      setFile(dropped)
      setError(null)
      setMetrics(null)
    } else {
      setError('Please drop a valid CSV file.')
    }
  }

  function handleFileChange(e) {
    const chosen = e.target.files[0]
    if (chosen) {
      setFile(chosen)
      setError(null)
      setMetrics(null)
    }
  }

  // ── Submit ───────────────────────────────────────────────────────────────
  async function handleTrain(e) {
    e.preventDefault()
    if (!file) { setError('Please select a CSV file first.'); return }

    setTraining(true)
    setError(null)
    setMetrics(null)

    try {
      const formData = new FormData()
      formData.append('csv_file', file)

      const res  = await fetch('/api/train', { method: 'POST', body: formData })
      const data = await res.json()

      if (!res.ok) throw new Error(data.error || 'Training failed.')
      setMetrics(data)
    } catch (err) {
      setError(err.message)
    } finally {
      setTraining(false)
    }
  }

  // ── Confusion matrix cell colours ────────────────────────────────────────
  function cmCellStyle(row, col, cm) {
    const max = Math.max(...cm.flat())
    const val = cm[row][col]
    const intensity = max > 0 ? val / max : 0
    if (row === col) {
      // correct predictions – green tint
      return {
        background: `rgba(82,184,82,${0.12 + intensity * 0.55})`,
        color: 'var(--text)',
      }
    }
    // errors – red tint
    return {
      background: val > 0 ? `rgba(224,82,82,${0.12 + intensity * 0.55})` : 'transparent',
      color: 'var(--text)',
    }
  }

  const pct = v => `${(v * 100).toFixed(2)}%`

  return (
    <div className="train-page">
      <div className="page-header" style={{ marginBottom: '2rem' }}>
        <h1 className="page-title">Train Model</h1>
        <p className="page-subtitle">
          Upload a labelled CSV dataset to retrain the Random Forest classifier.
          The CSV must contain an <code>is_malicious</code> column (0 = Normal, 1 = Malicious).
        </p>
      </div>

      {/* ── Upload Card ──────────────────────────────────────────────────── */}
      <form onSubmit={handleTrain}>
        <div className="card" style={{ marginBottom: '1.5rem' }}>
          <div className="card-header">
            <span className="card-icon">📂</span>
            <h2 className="card-title">Upload Training Dataset</h2>
          </div>

          <div
            className={`csv-drop-zone${dragOver ? ' drag-over' : ''}${file ? ' has-file' : ''}`}
            onDragOver={e => { e.preventDefault(); setDragOver(true) }}
            onDragLeave={() => setDragOver(false)}
            onDrop={handleDrop}
            onClick={() => fileRef.current?.click()}
            style={{ cursor: 'pointer' }}
          >
            <input
              ref={fileRef}
              type="file"
              accept=".csv"
              style={{ display: 'none' }}
              onChange={handleFileChange}
            />
            {file ? (
              <div className="drop-content">
                <div style={{ fontSize: '2rem' }}>✅</div>
                <div className="drop-label">{file.name}</div>
                <div className="drop-hint">
                  {(file.size / 1024).toFixed(1)} KB – click to replace
                </div>
              </div>
            ) : (
              <div className="drop-content">
                <div style={{ fontSize: '2.5rem' }}>📊</div>
                <div className="drop-label">Drop CSV here or click to browse</div>
                <div className="drop-hint">Requires an <code>is_malicious</code> label column</div>
              </div>
            )}
          </div>

          {error && (
            <div className="error-banner" style={{ marginTop: '1rem' }}>
              ⚠️ {error}
            </div>
          )}

          <div style={{ marginTop: '1.25rem', display: 'flex', justifyContent: 'flex-end' }}>
            <button
              type="submit"
              className="btn-primary"
              disabled={training || !file}
              style={{ minWidth: 160 }}
            >
              {training ? (
                <span className="loading-dots">Training<span>.</span><span>.</span><span>.</span></span>
              ) : (
                '🚀 Train Model'
              )}
            </button>
          </div>
        </div>
      </form>

      {/* ── Metrics Section ──────────────────────────────────────────────── */}
      {metrics && (
        <div className="metrics-section">
          {/* Summary banner */}
          <div className="result-header-card" style={{ marginBottom: '1.5rem' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '0.5rem' }}>
              <span style={{ fontSize: '1.6rem' }}>🎉</span>
              <h2 style={{ margin: 0, color: 'var(--success)' }}>Training Complete</h2>
            </div>
            <p style={{ color: 'var(--text-muted)', margin: 0 }}>
              Trained on <strong style={{ color: 'var(--text)' }}>{metrics.training_records.toLocaleString()}</strong> records,
              evaluated on <strong style={{ color: 'var(--text)' }}>{metrics.test_records.toLocaleString()}</strong> held-out records.
              The model is now active.
            </p>
          </div>

          {/* Metric cards row */}
          <div className="metrics-grid" style={{ marginBottom: '1.5rem' }}>
            {[
              { label: 'Accuracy',  value: pct(metrics.accuracy),  icon: '🎯', color: 'var(--gold)' },
              { label: 'Precision', value: pct(metrics.precision), icon: '🔬', color: 'var(--gold-light)' },
              { label: 'Recall',    value: pct(metrics.recall),    icon: '📡', color: '#6ab4f5' },
              { label: 'F1-Score',  value: pct(metrics.f1),        icon: '⚖️', color: 'var(--success)' },
            ].map(m => (
              <div key={m.label} className="metric-card">
                <div className="metric-icon">{m.icon}</div>
                <div className="metric-value" style={{ color: m.color }}>{m.value}</div>
                <div className="metric-label">{m.label}</div>
              </div>
            ))}
          </div>

          {/* Confusion matrix */}
          <div className="card" style={{ marginBottom: '1.5rem' }}>
            <div className="card-header">
              <span className="card-icon">🔲</span>
              <h2 className="card-title">Confusion Matrix</h2>
            </div>

            <div style={{ overflowX: 'auto' }}>
              <table className="cm-table">
                <thead>
                  <tr>
                    <th style={{ background: 'transparent', border: 'none' }}></th>
                    <th colSpan={2} style={{ textAlign: 'center', color: 'var(--text-muted)', fontWeight: 500 }}>
                      Predicted
                    </th>
                  </tr>
                  <tr>
                    <th></th>
                    <th>Normal</th>
                    <th>Malicious</th>
                  </tr>
                </thead>
                <tbody>
                  {['Normal', 'Malicious'].map((rowLabel, row) => (
                    <tr key={rowLabel}>
                      {row === 0 && (
                        <td
                          rowSpan={2}
                          style={{
                            writingMode: 'vertical-rl',
                            transform: 'rotate(180deg)',
                            textAlign: 'center',
                            color: 'var(--text-muted)',
                            fontWeight: 500,
                            padding: '0 0.5rem',
                            verticalAlign: 'middle',
                          }}
                        >
                          Actual
                        </td>
                      )}
                      <td className="cm-row-label">{rowLabel}</td>
                      {metrics.confusion_matrix[row].map((val, col) => (
                        <td
                          key={col}
                          className="cm-cell"
                          style={cmCellStyle(row, col, metrics.confusion_matrix)}
                        >
                          <div className="cm-val">{val.toLocaleString()}</div>
                          <div className="cm-sub">
                            {row === 0 && col === 0 && 'TN'}
                            {row === 0 && col === 1 && 'FP'}
                            {row === 1 && col === 0 && 'FN'}
                            {row === 1 && col === 1 && 'TP'}
                          </div>
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {/* Classification report */}
          <div className="card">
            <div className="card-header">
              <span className="card-icon">📋</span>
              <h2 className="card-title">Classification Report</h2>
            </div>
            <pre className="metrics-report">{metrics.classification_report}</pre>
          </div>
        </div>
      )}
    </div>
  )
}
